const fs=require('fs'),assert=require('assert/strict'),crypto=require('crypto'),png=require('./scripts/png.cjs');const d=fs.readFileSync('latest-fringe-audit-path.txt','utf8')+'/',raw=fs.readFileSync(d+'before.json'),before=JSON.parse(raw),p=structuredClone(before),li=198,key='8_0_2',changes=[],dec=c=>png.decode(Buffer.from(c.dataURL.split(',')[1],'base64'));assert.equal(p.layers[li].name,'前发');assert(p.layers[li].visible&&p.layers[li].sheetIndex===8);
function world(c){const a=dec(c),r=c.placement||{x:0,y:0},data=new Uint8Array(40*40*4);assert(!c.placement||(r.w===a.width&&r.h===a.height));for(let y=0;y<a.height;y++)for(let x=0;x<a.width;x++){const xx=x+r.x,yy=y+r.y;if(xx>=0&&xx<40&&yy>=0&&yy<40)data.set(a.data.subarray((y*a.width+x)*4,(y*a.width+x)*4+4),(yy*40+xx)*4);}return data;}
function headY(fi){const l=p.layers.find(l=>l.sheetIndex===8&&l.name==='head'&&l.frameData['8_0_'+fi]),im=world(l.frameData['8_0_'+fi]);for(let y=0;y<40;y++)for(let x=0;x<40;x++)if(im[(y*40+x)*4+3])return y;throw Error('empty head');}
const source=world(before.layers[li].frameData[key]),exceptions=[];for(let fi of [0,1,3]){const k='8_0_'+fi,c=p.layers[li].frameData[k],im=dec(c),r=c.placement||{x:0,y:0},old=world(c),dy=headY(fi)-headY(2),out=new Uint8Array(im.data.length),canonical=new Uint8Array(40*40*4);for(let y=0;y<40;y++)for(let x=0;x<40;x++){const sy=y-dy;if(sy>=0&&sy<40)canonical.set(source.subarray((sy*40+x)*4,(sy*40+x)*4+4),(y*40+x)*4);}
 // Preserve the existing central-fringe settling pose, not the old cap/side-lock styling.
 const preserved=new Set();for(let sy=15;sy<=18;sy++)for(let x=13;x<=22;x++){const y=sy+dy,i=(y*40+x)*4;canonical.set(old.subarray(i,i+4),i);preserved.add(i/4);}
 const tail=(24+dy)*40+7;canonical.fill(0,tail*4,tail*4+4);preserved.add(tail);
 // The user's separately edited right lock tip in frame one is retained.
 if(fi===0)for(const [x,y]of [[22,21],[22,22]]){const i=(y*40+x)*4;canonical.set(old.subarray(i,i+4),i);preserved.add(i/4);}
 for(let y=0;y<40;y++)for(let x=0;x<40;x++){const i=(y*40+x)*4;if(!canonical[i+3])continue;const tx=x-r.x,ty=y-r.y;assert(tx>=0&&ty>=0&&tx<im.width&&ty<im.height,'copy would crop hair');out.set(canonical.subarray(i,i+4),(ty*im.width+tx)*4);}
 let n=0;for(let i=0;i<out.length;i+=4)if([0,1,2,3].some(q=>im.data[i+q]!==out[i+q]))n++;c.dataURL='data:image/png;base64,'+png.encode(im.width,im.height,out).toString('base64');const actual=world(c);assert.deepEqual(actual,canonical);for(let y=0;y<40;y++)for(let x=0;x<40;x++){const i=(y*40+x)*4,sy=y-dy;if(preserved.has(i/4))continue;const expected=sy>=0&&sy<40?[...source.subarray((sy*40+x)*4,(sy*40+x)*4+4)]:[0,0,0,0];assert.deepEqual([...actual.subarray(i,i+4)],expected,'full approved fringe must match outside real motion');}changes.push({layer:li,key:k,headOffset:dy,changedPixels:n});exceptions.push({key:k,sourceCoordinates:{centralFringe:[13,15,22,18],outerCurl:[7,24]},separateUserTip:fi===0?[[22,21],[22,22]]:[]});}
const restore=structuredClone(p);for(const c of changes)restore.layers[c.layer].frameData[c.key]=before.layers[c.layer].frameData[c.key];assert.deepEqual(restore,before);fs.writeFileSync(d+'restore-extra-copy.json',JSON.stringify(restore));assert.deepEqual(JSON.parse(fs.readFileSync(d+'restore-extra-copy.json')),before);assert.deepEqual(p.layers[li].frameData[key],before.layers[li].frameData[key]);fs.writeFileSync(d+'sha256.txt',crypto.createHash('sha256').update(raw).digest('hex'));fs.writeFileSync(d+'candidate.json',JSON.stringify(p));fs.writeFileSync(d+'diff.json',JSON.stringify({changes,exceptions},null,2));fs.writeFileSync(d+'verification.json',JSON.stringify({changes,wholeApprovedFringeCompared:true,onlyDocumentedNativeMotionAndUserTipExempted:true,sourceThirdUnchanged:true,allFrontDirectionFramesAndOtherDataUnchanged:true,restoreExtraCopyVerified:true,browserChecked:false},null,2));console.log('PASS full-fringe synchronization',JSON.stringify(changes));
